#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;

    long long ans = n;

    if (m > 0) {
        for (long long divisor = m; divisor <= n;) {
            ans += n / divisor;

            if (divisor > n / 2) break;
            divisor *= 2;
        }
    }

    cout << ans << '\n';
    return 0;
}

